// Social Manager: generated by `npm run bundle` from src/. Do not edit; edit src/ and rebuild.

// ---- src/core.js ----
/**
 * Shared pieces with no Google services in them: errors, ids, input checks and the platform list.
 */

const API_VERSION = '1.0.0';
const NAME_RE = /^[a-z0-9-]{1,40}$/;
const JOB_STATUSES = ['queued', 'running', 'done', 'failed', 'cancelled'];
const MAX_ATTEMPTS = 3;
// Each upload chunk is read from Drive and sent to the platform in one request.
// It must stay under Apps Script's 50 MB fetch limit and be a multiple of 256 KB.
let CHUNK_BYTES = 20 * 1024 * 1024;
// A worker run stops starting new work after this long, well inside Apps Script's 6 minute limit.
let WORK_BUDGET_MS = 4 * 60 * 1000;

class ApiError extends Error {
  constructor(code, message, details) {
    super(message);
    this.code = code;
    this.details = details;
  }
}

/** Every publishing platform. Adding Instagram later means one new file and one line here. */
function platforms_() {
  return { youtube: YouTube };
}

function adapterFor_(name) {
  const a = platforms_()[name];
  if (!a) throw new ApiError('invalid', `Unknown platform "${name}". Platforms: ${Object.keys(platforms_()).join(', ')}`);
  return a;
}

// ---------- input checks used by the adapters ----------

function optText_(v, field, max) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v !== 'string') throw new ApiError('invalid', `${field} must be text`);
  if (v.length > max) throw new ApiError('invalid', `${field} is ${v.length} characters; the limit is ${max}`);
  return v;
}

function optBool_(v, field) {
  if (v === undefined || v === null) return null;
  if (typeof v !== 'boolean') throw new ApiError('invalid', `${field} must be true or false`);
  return v;
}

/** A file the service reads: {"driveFileId": "..."}. */
function optFile_(v, field) {
  if (v === undefined || v === null) return null;
  if (!v || typeof v !== 'object' || typeof v.driveFileId !== 'string' || !v.driveFileId) {
    throw new ApiError('invalid', `${field} must look like {"driveFileId": "..."}`);
  }
  return { driveFileId: v.driveFileId };
}

function optFutureTime_(v, field, now) {
  if (v === undefined || v === null || v === '') return null;
  const d = new Date(v);
  if (typeof v !== 'string' || isNaN(d.getTime())) throw new ApiError('invalid', `${field} must be an ISO time like 2026-11-20T14:00:00Z`);
  if (d.getTime() < now.getTime() + 15 * 60 * 1000) throw new ApiError('invalid', `${field} must be at least 15 minutes in the future`);
  return d.toISOString();
}

// ---------- jobs ----------

function newJobId_(now, rand) {
  return `j-${now.toISOString().replace(/\D/g, '').slice(0, 12)}-${rand}`;
}

/** What callers see: everything except the adapter's private working state. */
function presentJob_(job) {
  const s = job.state || {};
  const out = {
    id: job.id, key: job.key || null, platform: job.platform, status: job.status, title: job.title,
    attempts: job.attempts || 0, notBefore: job.notBefore || null, createdAt: job.createdAt, updatedAt: job.updatedAt,
    caller: job.caller, result: job.result || null, error: job.error || null,
  };
  if (job.status === 'queued' || job.status === 'running') {
    out.progress = { step: s.step || null, uploadedBytes: s.offset || 0, totalBytes: s.size || null };
  }
  return out;
}

/** The oldest queued job that is allowed to run now. A job left "running" by a crashed run counts as queued after 10 minutes. */
function pickNextJob_(jobs, now) {
  const t = now.getTime();
  return jobs
    .filter((j) => (j.status === 'queued' && (!j.notBefore || new Date(j.notBefore).getTime() <= t))
      || (j.status === 'running' && new Date(j.updatedAt).getTime() < t - 10 * 60 * 1000))
    .sort((a, b) => (a.createdAt < b.createdAt ? -1 : 1))[0] || null;
}

/** Decides what happens to a job after a step throws. */
function afterError_(job, err, now) {
  const retry = err && err.details && err.details.retry;
  const message = String(err && err.message ? err.message : err);
  if (retry === 'quota') {
    // Daily quota resets at midnight Pacific time; try again in an hour rather than computing it exactly.
    return { status: 'queued', notBefore: new Date(now.getTime() + 60 * 60 * 1000).toISOString(), error: `Waiting for quota: ${message}` };
  }
  const attempts = (job.attempts || 0) + 1;
  if (retry === 'transient' && attempts < MAX_ATTEMPTS) {
    return { status: 'queued', attempts, notBefore: new Date(now.getTime() + 5 * 60 * 1000).toISOString(), error: `Will retry: ${message}` };
  }
  return { status: 'failed', attempts, error: message };
}

// ---- src/google.js ----
/**
 * Small helpers for calling Google REST APIs as the script owner (Drive and YouTube).
 */

function google_(method, url, opts) {
  const o = opts || {};
  const params = {
    method,
    muteHttpExceptions: true,
    headers: Object.assign({ Authorization: `Bearer ${ScriptApp.getOAuthToken()}` }, o.headers || {}),
  };
  if (o.json !== undefined) {
    params.contentType = 'application/json; charset=UTF-8';
    params.payload = JSON.stringify(o.json);
  } else if (o.payload !== undefined) {
    params.payload = o.payload;
    if (o.contentType) params.contentType = o.contentType;
  }
  return UrlFetchApp.fetch(url, params);
}

/** Calls an API and returns its JSON, or throws an ApiError that says whether a retry can help. */
function googleJson_(method, url, opts) {
  const r = google_(method, url, opts);
  const code = r.getResponseCode();
  if (code >= 200 && code < 300) {
    const text = r.getContentText();
    return text ? JSON.parse(text) : {};
  }
  throw upstreamError_(r);
}

function upstreamError_(r) {
  const code = r.getResponseCode();
  let reason = '';
  let message = '';
  try {
    const e = JSON.parse(r.getContentText()).error || {};
    reason = (e.errors && e.errors[0] && e.errors[0].reason) || e.status || '';
    message = e.message || '';
  } catch (err) {
    message = String(r.getContentText()).slice(0, 300);
  }
  let retry = false;
  if (['quotaExceeded', 'uploadLimitExceeded', 'dailyLimitExceeded'].includes(reason)) retry = 'quota';
  else if (code >= 500 || code === 429 || ['rateLimitExceeded', 'userRateLimitExceeded', 'backendError'].includes(reason)) retry = 'transient';
  return new ApiError('upstream', `Google answered ${code}${reason ? ` (${reason})` : ''}: ${message}`, { status: code, reason, retry });
}

function header_(r, name) {
  const h = r.getHeaders() || {};
  const k = Object.keys(h).find((x) => x.toLowerCase() === name.toLowerCase());
  return k ? h[k] : null;
}

// ---------- Drive ----------

const DRIVE = 'https://www.googleapis.com/drive/v3/files';

function driveMeta_(id) {
  return googleJson_('get', `${DRIVE}/${encodeURIComponent(id)}?fields=name,size,mimeType&supportsAllDrives=true`);
}

/** Bytes start..end (inclusive) of a Drive file, so files larger than 50 MB can be read in parts. */
function driveRange_(id, start, end) {
  const r = google_('get', `${DRIVE}/${encodeURIComponent(id)}?alt=media&supportsAllDrives=true`, { headers: { Range: `bytes=${start}-${end}` } });
  if (r.getResponseCode() !== 206 && r.getResponseCode() !== 200) throw upstreamError_(r);
  return r.getContent();
}

function driveBytes_(id) {
  const r = google_('get', `${DRIVE}/${encodeURIComponent(id)}?alt=media&supportsAllDrives=true`);
  if (r.getResponseCode() !== 200) throw upstreamError_(r);
  return r.getContent();
}

// ---- src/youtube.js ----
/**
 * YouTube adapter. Uploads a video from Drive with a resumable upload (any size, in chunks, across
 * several worker runs if needed), or edits a video already on YouTube, then sets the thumbnail,
 * captions and playlists. Every step records what it finished, so a retry never repeats work.
 */

const YT = 'https://www.googleapis.com/youtube/v3';
const YT_UPLOAD = 'https://www.googleapis.com/upload/youtube/v3';
const YT_PRIVACY = ['private', 'unlisted', 'public'];

const YouTube = {
  name: 'youtube',

  /** Checks a publish request and returns the clean version that is stored on the job. */
  validate(p, now) {
    const video = optFile_(p.video, 'video');
    const videoId = optText_(p.videoId, 'videoId', 20);
    if (!video && !videoId) throw new ApiError('invalid', 'Send video: {"driveFileId": ...} to upload, or videoId to edit a video already on YouTube');
    if (video && videoId) throw new ApiError('invalid', 'Send video or videoId, not both');

    const title = optText_(p.title, 'title', 100);
    if (video && !title) throw new ApiError('invalid', 'title is required for an upload');
    if (title && /[<>]/.test(title)) throw new ApiError('invalid', 'title cannot contain < or >');
    const description = optText_(p.description, 'description', 5000);
    if (description && /[<>]/.test(description)) throw new ApiError('invalid', 'description cannot contain < or >');

    let tags = null;
    if (p.tags !== undefined && p.tags !== null) {
      if (!Array.isArray(p.tags) || p.tags.some((t) => typeof t !== 'string')) throw new ApiError('invalid', 'tags must be a list of text');
      tags = p.tags.map((t) => t.trim()).filter(Boolean);
      // YouTube counts a tag with a space as if it had quotes around it, plus a comma between tags.
      const len = tags.reduce((n, t) => n + t.length + (t.includes(' ') ? 2 : 0), 0) + Math.max(tags.length - 1, 0);
      if (len > 500) throw new ApiError('invalid', `tags add up to ${len} characters; the limit is 500`);
    }

    const categoryId = p.categoryId === undefined || p.categoryId === null ? null : String(p.categoryId);
    if (categoryId && !/^\d+$/.test(categoryId)) throw new ApiError('invalid', 'categoryId must be a number like 28');

    const publishAt = optFutureTime_(p.publishAt, 'publishAt', now);
    let privacy = optText_(p.privacy, 'privacy', 10);
    if (privacy && !YT_PRIVACY.includes(privacy)) throw new ApiError('invalid', `privacy must be one of ${YT_PRIVACY.join(', ')}`);
    if (publishAt && privacy && privacy !== 'private') {
      throw new ApiError('invalid', 'A scheduled video must be private until publishAt; leave privacy out or send "private"');
    }
    if (publishAt) privacy = 'private';
    if (video && !privacy) privacy = 'private';

    let captions = [];
    if (p.captions !== undefined && p.captions !== null) {
      if (!Array.isArray(p.captions)) throw new ApiError('invalid', 'captions must be a list');
      captions = p.captions.map((c, i) => {
        const f = optFile_(c, `captions[${i}]`);
        const language = optText_(c.language, `captions[${i}].language`, 20);
        if (!language) throw new ApiError('invalid', `captions[${i}].language is required, like "en"`);
        return { driveFileId: f.driveFileId, language, name: optText_(c.name, `captions[${i}].name`, 150) || '' };
      });
    }

    let playlists = [];
    if (p.playlists !== undefined && p.playlists !== null) {
      if (!Array.isArray(p.playlists) || p.playlists.some((x) => typeof x !== 'string' || !x)) throw new ApiError('invalid', 'playlists must be a list of playlist ids or exact playlist titles');
      playlists = p.playlists;
    }

    return {
      video, videoId, title, description, tags, categoryId: categoryId || (video ? '22' : null),
      language: optText_(p.language, 'language', 20),
      madeForKids: video ? optBool_(p.madeForKids, 'madeForKids') === true : optBool_(p.madeForKids, 'madeForKids'),
      aiGenerated: optBool_(p.aiGenerated, 'aiGenerated'),
      privacy, publishAt,
      thumbnail: optFile_(p.thumbnail, 'thumbnail'),
      captions, playlists,
    };
  },

  steps(post) {
    return [post.video ? 'upload' : 'edit', 'thumbnail', 'captions', 'playlists', 'check'];
  },

  run(step, job, ctx) {
    return YT_STEPS[step](job.post, job.state, ctx);
  },

  /** The channel the service posts to. */
  whoami() {
    const r = googleJson_('get', `${YT}/channels?part=snippet&mine=true`);
    const c = (r.items || [])[0];
    if (!c) throw new ApiError('not_found', 'This Google account has no YouTube channel');
    return { id: c.id, title: c.snippet.title, url: `https://www.youtube.com/channel/${c.id}` };
  },
};

function ytSnippet_(p, base) {
  const s = {};
  ['title', 'description', 'tags', 'categoryId', 'defaultLanguage', 'defaultAudioLanguage'].forEach((k) => {
    if (base && base[k] !== undefined) s[k] = base[k];
  });
  if (p.title) s.title = p.title;
  if (p.description !== null) s.description = p.description;
  if (p.tags) s.tags = p.tags;
  if (p.categoryId) s.categoryId = p.categoryId;
  if (p.language) { s.defaultLanguage = p.language; s.defaultAudioLanguage = p.language; }
  return s;
}

function ytStatus_(p, base) {
  const s = {};
  ['privacyStatus', 'publishAt', 'embeddable', 'license', 'publicStatsViewable', 'selfDeclaredMadeForKids', 'containsSyntheticMedia'].forEach((k) => {
    if (base && base[k] !== undefined) s[k] = base[k];
  });
  if (p.privacy) s.privacyStatus = p.privacy;
  if (p.publishAt) s.publishAt = p.publishAt;
  else if (p.privacy && p.privacy !== 'private') delete s.publishAt;
  if (p.madeForKids !== null) s.selfDeclaredMadeForKids = p.madeForKids;
  if (p.aiGenerated !== null) s.containsSyntheticMedia = p.aiGenerated;
  return s;
}

const YT_STEPS = {
  upload(p, s, ctx) {
    if (s.videoId) return 'next';
    if (!s.size) {
      const m = driveMeta_(p.video.driveFileId);
      s.size = Number(m.size);
      s.mime = m.mimeType || 'video/mp4';
      if (!s.size) throw new ApiError('invalid', 'The video file in Drive is empty');
    }
    if (!s.session) {
      const r = google_('post', `${YT_UPLOAD}/videos?uploadType=resumable&part=snippet,status`, {
        json: { snippet: ytSnippet_(p), status: ytStatus_(p) },
        headers: { 'X-Upload-Content-Length': String(s.size), 'X-Upload-Content-Type': s.mime },
      });
      if (r.getResponseCode() !== 200) throw upstreamError_(r);
      s.session = header_(r, 'Location');
      s.offset = 0;
      ctx.save();
    }
    while (s.offset < s.size) {
      if (ctx.outOfTime()) return 'pause';
      const end = Math.min(s.offset + CHUNK_BYTES, s.size) - 1;
      const r = google_('put', s.session, {
        payload: driveRange_(p.video.driveFileId, s.offset, end),
        contentType: s.mime,
        headers: { 'Content-Range': `bytes ${s.offset}-${end}/${s.size}` },
      });
      const code = r.getResponseCode();
      if (code === 200 || code === 201) {
        s.videoId = JSON.parse(r.getContentText()).id;
        s.offset = s.size;
        ctx.save();
        break;
      }
      if (code === 308) {
        const range = header_(r, 'Range'); // "bytes=0-12345": what YouTube has so far
        s.offset = range ? Number(String(range).split('-')[1]) + 1 : 0;
        ctx.save();
        continue;
      }
      if (code === 404 || code === 410) {
        // The upload session expired (they last about a week); start the upload again.
        delete s.session;
        s.offset = 0;
        ctx.save();
        throw new ApiError('upstream', 'The upload session expired; starting the upload again', { retry: 'transient' });
      }
      throw upstreamError_(r);
    }
    return 'next';
  },

  edit(p, s) {
    if (s.videoId) return 'next';
    const r = googleJson_('get', `${YT}/videos?part=snippet,status&id=${encodeURIComponent(p.videoId)}`);
    const v = (r.items || [])[0];
    if (!v) throw new ApiError('not_found', `No video ${p.videoId} on this channel`);
    googleJson_('put', `${YT}/videos?part=snippet,status`, {
      json: { id: p.videoId, snippet: ytSnippet_(p, v.snippet), status: ytStatus_(p, v.status) },
    });
    s.videoId = p.videoId;
    return 'next';
  },

  thumbnail(p, s, ctx) {
    if (!p.thumbnail || s.thumbnailDone) return 'next';
    ctx.optional('thumbnail', () => {
      const m = driveMeta_(p.thumbnail.driveFileId);
      if (Number(m.size) > 2 * 1024 * 1024) throw new ApiError('invalid', 'The thumbnail is over YouTube\'s 2 MB limit');
      const r = google_('post', `${YT_UPLOAD}/thumbnails/set?videoId=${encodeURIComponent(s.videoId)}&uploadType=media`, {
        payload: driveBytes_(p.thumbnail.driveFileId), contentType: m.mimeType || 'image/jpeg',
      });
      if (r.getResponseCode() !== 200) throw upstreamError_(r);
    });
    s.thumbnailDone = true;
    return 'next';
  },

  captions(p, s, ctx) {
    s.captionsDone = s.captionsDone || [];
    p.captions.forEach((c, i) => {
      if (s.captionsDone.includes(i)) return;
      ctx.optional(`captions ${c.language}`, () => {
        const boundary = `pub${Date.now()}`;
        const head = `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({ snippet: { videoId: s.videoId, language: c.language, name: c.name, isDraft: false } })}\r\n--${boundary}\r\nContent-Type: application/octet-stream\r\n\r\n`;
        const body = Utilities.newBlob(head).getBytes()
          .concat(driveBytes_(c.driveFileId))
          .concat(Utilities.newBlob(`\r\n--${boundary}--`).getBytes());
        const r = google_('post', `${YT_UPLOAD}/captions?part=snippet&uploadType=multipart`, { payload: body, contentType: `multipart/related; boundary=${boundary}` });
        if (r.getResponseCode() !== 200) throw upstreamError_(r);
      });
      s.captionsDone.push(i);
      ctx.save();
    });
    return 'next';
  },

  playlists(p, s, ctx) {
    s.playlistsDone = s.playlistsDone || [];
    const todo = p.playlists.filter((x) => !s.playlistsDone.includes(x));
    if (!todo.length) return 'next';
    let mine = null;
    todo.forEach((want) => {
      ctx.optional(`playlist ${want}`, () => {
        if (!mine) mine = ytMyPlaylists_();
        const hit = mine.find((pl) => pl.id === want) || mine.find((pl) => pl.title === want);
        if (!hit) throw new ApiError('not_found', `No playlist with id or title "${want}" on this channel`);
        googleJson_('post', `${YT}/playlistItems?part=snippet`, {
          json: { snippet: { playlistId: hit.id, resourceId: { kind: 'youtube#video', videoId: s.videoId } } },
        });
      });
      s.playlistsDone.push(want);
      ctx.save();
    });
    return 'next';
  },

  /** Reads the video back, so the result shows what YouTube actually did. */
  check(p, s, ctx) {
    const r = googleJson_('get', `${YT}/videos?part=status,snippet&id=${encodeURIComponent(s.videoId)}`);
    const v = (r.items || [])[0];
    if (!v) throw new ApiError('upstream', `YouTube does not list video ${s.videoId}`, { retry: 'transient' });
    const st = v.status || {};
    if (p.privacy && st.privacyStatus !== p.privacy) {
      ctx.warn(`Asked for ${p.privacy} but YouTube set ${st.privacyStatus}. If this was an API upload, the API project is probably not audited yet (see the FAQ).`);
    }
    if (p.publishAt && !st.publishAt) ctx.warn('Asked for a scheduled time but YouTube did not keep it. See the FAQ about the API audit.');
    ctx.result({
      videoId: s.videoId,
      url: `https://youtu.be/${s.videoId}`,
      studioUrl: `https://studio.youtube.com/video/${s.videoId}/edit`,
      title: v.snippet && v.snippet.title,
      privacy: st.privacyStatus,
      publishAt: st.publishAt || null,
      uploadStatus: st.uploadStatus || null,
    });
    return 'next';
  },
};

function ytMyPlaylists_() {
  const out = [];
  let page = '';
  do {
    const r = googleJson_('get', `${YT}/playlists?part=snippet&mine=true&maxResults=50${page ? `&pageToken=${page}` : ''}`);
    (r.items || []).forEach((pl) => out.push({ id: pl.id, title: pl.snippet.title }));
    page = r.nextPageToken || '';
  } while (page);
  return out;
}

// ---- src/store.js ----
/**
 * Jobs live in the "Jobs" tab of the Social Manager spreadsheet, one row each, so the owner can read them.
 */

const JOB_COLS = ['id', 'key', 'platform', 'status', 'title', 'attempts', 'notBefore', 'createdAt', 'updatedAt', 'caller', 'result', 'error', 'post', 'state'];
const JSON_COLS = ['result', 'post', 'state'];

function props_() {
  return PropertiesService.getScriptProperties();
}

function jobsSheet_() {
  const id = props_().getProperty('SHEET_ID');
  if (!id) throw new ApiError('not_set_up', 'Run setup() in the Apps Script editor first');
  return SpreadsheetApp.openById(id).getSheetByName('Jobs');
}

function withLock_(fn) {
  const lock = LockService.getScriptLock();
  if (!lock.tryLock(20000)) throw new ApiError('busy', 'The service is busy; try again in a few seconds', { retry: 'transient' });
  try { return fn(); } finally { lock.releaseLock(); }
}

function rowToJob_(row) {
  const j = {};
  JOB_COLS.forEach((c, i) => {
    const v = row[i];
    j[c] = JSON_COLS.includes(c) ? (v ? JSON.parse(v) : null) : (v === '' ? null : v);
  });
  j.attempts = Number(j.attempts || 0);
  j.state = j.state || {};
  return j;
}

function jobToRow_(j) {
  return JOB_COLS.map((c) => {
    const v = j[c];
    if (JSON_COLS.includes(c)) return v ? JSON.stringify(v) : '';
    return v === null || v === undefined ? '' : v;
  });
}

function allJobs_() {
  const sh = jobsSheet_();
  const n = sh.getLastRow() - 1;
  if (n < 1) return [];
  return sh.getRange(2, 1, n, JOB_COLS.length).getValues().filter((r) => r[0]).map(rowToJob_);
}

function findJob_(id) {
  const sh = jobsSheet_();
  const n = sh.getLastRow() - 1;
  if (n < 1) return null;
  const hit = sh.getRange(2, 1, n, 1).createTextFinder(String(id)).matchEntireCell(true).findNext();
  if (!hit) return null;
  return { row: hit.getRow(), job: rowToJob_(sh.getRange(hit.getRow(), 1, 1, JOB_COLS.length).getValues()[0]) };
}

function jobOrThrow_(id) {
  const f = findJob_(id);
  if (!f) throw new ApiError('not_found', `No job ${id}`);
  return f;
}

function insertJob_(job) {
  jobsSheet_().appendRow(jobToRow_(job));
}

function saveJob_(job) {
  job.updatedAt = new Date().toISOString();
  withLock_(() => {
    const f = jobOrThrow_(job.id);
    jobsSheet_().getRange(f.row, 1, 1, JOB_COLS.length).setValues([jobToRow_(job)]);
  });
}

// ---- src/worker.js ----
/**
 * The worker: a time trigger runs runQueue every 5 minutes and works through queued jobs one at a time.
 * Long uploads stop before Apps Script's time limit and carry on in the next run.
 */

function runQueue() {
  return runQueue_();
}

function runQueue_() {
  const p = props_();
  // Only one worker at a time. A crashed worker's claim runs out after 7 minutes.
  const claimed = withLock_(() => {
    if (Number(p.getProperty('WORKER_UNTIL') || 0) > Date.now()) return false;
    p.setProperty('WORKER_UNTIL', String(Date.now() + 7 * 60 * 1000));
    return true;
  });
  if (!claimed) return { ran: [], note: 'Another worker run is busy' };
  const started = Date.now();
  const ran = [];
  try {
    do {
      const job = pickNextJob_(allJobs_(), new Date());
      if (!job) break;
      const paused = runJob_(job, started) === 'paused';
      ran.push(presentJob_(job));
      if (paused) break; // out of time mid-upload; the next run carries on
    } while (Date.now() - started < WORK_BUDGET_MS);
  } finally {
    p.deleteProperty('WORKER_UNTIL');
  }
  return { ran };
}

function runJob_(job, started) {
  const adapter = adapterFor_(job.platform);
  const steps = adapter.steps(job.post);
  job.status = 'running';
  job.notBefore = null;
  const warnings = (job.result && job.result.warnings) || [];
  const ctx = {
    outOfTime: () => Date.now() - started > WORK_BUDGET_MS,
    save: () => saveJob_(job),
    warn: (msg) => { if (!warnings.includes(msg)) warnings.push(msg); },
    result: (r) => { job.result = Object.assign({}, r, { warnings }); },
    /** For extras (thumbnail, captions, playlists): a failure that a retry can't fix becomes a warning, not a failed job. */
    optional: (what, fn) => {
      try { fn(); } catch (err) {
        if (err && err.details && err.details.retry) throw err;
        ctx.warn(`${what}: ${err && err.message ? err.message : err}`);
      }
    },
  };
  saveJob_(job);
  try {
    for (let i = job.state.stepIndex || 0; i < steps.length; i++) {
      job.state.step = steps[i];
      if (adapter.run(steps[i], job, ctx) === 'pause') {
        job.status = 'queued';
        saveJob_(job);
        return 'paused';
      }
      job.state.stepIndex = i + 1;
      saveJob_(job);
    }
    job.status = 'done';
    job.error = null;
    if (!job.result) job.result = { warnings };
  } catch (err) {
    console.error(err && err.stack ? err.stack : err);
    Object.assign(job, afterError_(job, err, new Date()));
  }
  saveJob_(job);
}

// ---- src/api.js ----
/**
 * Web app entry points and the API actions.
 *
 * Every call: GET ?action=...&token=... or POST with a JSON body {"action": ..., "token": ..., ...}.
 * Apps Script always answers HTTP 200, so success or failure is in the body:
 *   {"ok": true, ...}  or  {"ok": false, "error": {"code": "...", "message": "...", "details": {...}}}
 */

function doGet(e) { return handle_(e, 'GET'); }
function doPost(e) { return handle_(e, 'POST'); }

const ROUTES = {
  health: { auth: false, fn: health_ },
  platforms: { fn: platformsInfo_ },
  channel: { fn: (req) => adapterFor_(req.platform || 'youtube').whoami() },
  publish: { write: true, fn: publish_ },
  get: { fn: (req) => ({ job: presentJob_(jobByIdOrKey_(req)) }) },
  list: { fn: list_ },
  retry: { write: true, fn: retry_ },
  cancel: { write: true, fn: cancel_ },
  run: { write: true, admin: true, fn: () => runQueue_() },
  createToken: { write: true, admin: true, fn: createToken_ },
  revokeToken: { write: true, admin: true, fn: revokeToken_ },
  listTokens: { admin: true, fn: listTokens_ },
};

function handle_(e, method) {
  try {
    const req = parseRequest_(e, method);
    const route = ROUTES[req.action || 'health'];
    if (!route) throw new ApiError('unknown_action', `Unknown action "${req.action}". Actions: ${Object.keys(ROUTES).join(', ')}`);
    if (route.write && method !== 'POST') throw new ApiError('method_not_allowed', `${req.action} needs POST`);
    const caller = route.auth === false ? null : authenticate_(req.token);
    if (route.admin && !caller.admin) throw new ApiError('forbidden', 'This action needs an admin token.');
    return json_(Object.assign({ ok: true }, route.fn(req, caller)));
  } catch (err) {
    if (err instanceof ApiError) {
      return json_({ ok: false, error: { code: err.code, message: err.message, details: err.details || null } });
    }
    console.error(err && err.stack ? err.stack : err);
    return json_({ ok: false, error: { code: 'internal', message: String(err && err.message ? err.message : err), details: null } });
  }
}

function parseRequest_(e, method) {
  const req = Object.assign({}, (e && e.parameter) || {});
  if (method === 'POST' && e && e.postData && e.postData.contents) {
    let body;
    try { body = JSON.parse(e.postData.contents); } catch (err) { throw new ApiError('bad_json', 'The POST body must be JSON.'); }
    if (!body || typeof body !== 'object' || Array.isArray(body)) throw new ApiError('bad_json', 'The POST body must be a JSON object.');
    Object.assign(req, body);
  }
  return req;
}

function json_(o) {
  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);
}

// ---------- auth: tokens are stored only as SHA-256 hashes in Script Properties ----------

function sha256Hex_(s) {
  return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(s), Utilities.Charset.UTF_8)
    .map((b) => ((b + 256) % 256).toString(16).padStart(2, '0')).join('');
}

function tokens_() {
  return JSON.parse(props_().getProperty('TOKENS') || '{}');
}

function authenticate_(token) {
  if (!token) throw new ApiError('unauthorized', 'token is required');
  const entry = tokens_()[sha256Hex_(token)];
  if (!entry) throw new ApiError('unauthorized', 'Unknown or revoked token');
  return entry;
}

/** Creates a token for a named client. The plain token is returned once and never stored. */
function issueToken_(name, admin) {
  if (!NAME_RE.test(String(name || ''))) throw new ApiError('invalid', 'name must be lowercase letters, digits or dashes (max 40)');
  const all = tokens_();
  if (Object.keys(all).some((h) => all[h].name === name)) throw new ApiError('conflict', `A token named ${name} exists; revoke it first`);
  const token = Utilities.getUuid().replace(/-/g, '') + Utilities.getUuid().replace(/-/g, '');
  all[sha256Hex_(token)] = { name, admin: !!admin, createdAt: new Date().toISOString() };
  props_().setProperty('TOKENS', JSON.stringify(all));
  return token;
}

function createToken_(req) {
  return withLock_(() => ({ name: req.name, admin: req.admin === true, token: issueToken_(req.name, req.admin === true) }));
}

function revokeToken_(req, caller) {
  return withLock_(() => {
    const all = tokens_();
    const hashes = Object.keys(all).filter((h) => all[h].name === req.name);
    if (!hashes.length) throw new ApiError('not_found', `No token named ${req.name}`);
    if (req.name === caller.name) throw new ApiError('invalid', 'You cannot revoke the token you are calling with');
    hashes.forEach((h) => { delete all[h]; });
    props_().setProperty('TOKENS', JSON.stringify(all));
    return { revoked: req.name };
  });
}

function listTokens_() {
  const all = tokens_();
  return { tokens: Object.keys(all).map((h) => all[h]) };
}

// ---------- jobs ----------

function health_() {
  return { service: 'social-manager', version: API_VERSION, platforms: Object.keys(platforms_()), time: new Date().toISOString() };
}

function platformsInfo_() {
  return { platforms: Object.keys(platforms_()) };
}

function jobByIdOrKey_(req) {
  if (req.id) return jobOrThrow_(req.id).job;
  if (req.key) {
    const j = allJobs_().filter((x) => x.key === String(req.key) && x.status !== 'cancelled').pop();
    if (!j) throw new ApiError('not_found', `No job with key ${req.key}`);
    return j;
  }
  throw new ApiError('invalid', 'Send id or key');
}

/**
 * Queues a post. With a key, sending the same post again returns the first job instead of posting twice,
 * so a caller can safely retry after a timeout.
 */
function publish_(req, caller) {
  const adapter = adapterFor_(req.platform);
  const now = new Date();
  const post = adapter.validate(req, now);
  const key = optText_(req.key, 'key', 100);
  return withLock_(() => {
    if (key) {
      const prior = allJobs_().find((j) => j.key === key && j.status !== 'cancelled');
      if (prior) return { job: presentJob_(prior), existing: true };
    }
    const iso = now.toISOString();
    const job = {
      id: newJobId_(now, Utilities.getUuid().slice(0, 4)), key, platform: adapter.name, status: 'queued',
      title: post.title || post.videoId || '', attempts: 0, notBefore: null, createdAt: iso, updatedAt: iso,
      caller: caller.name, result: null, error: null, post, state: {},
    };
    insertJob_(job);
    return { job: presentJob_(job), existing: false };
  });
}

function list_(req) {
  if (req.status && !JOB_STATUSES.includes(req.status)) throw new ApiError('invalid', `status must be one of ${JOB_STATUSES.join(', ')}`);
  const limit = Math.min(Math.max(Number(req.limit) || 20, 1), 200);
  const jobs = allJobs_()
    .filter((j) => (!req.status || j.status === req.status) && (!req.platform || j.platform === req.platform))
    .sort((a, b) => (a.createdAt < b.createdAt ? 1 : -1))
    .slice(0, limit);
  return { jobs: jobs.map(presentJob_) };
}

/** Puts a failed job back in the queue. It carries on from the step that failed, so nothing is posted twice. */
function retry_(req) {
  const job = jobOrThrow_(req.id).job;
  if (job.status !== 'failed') throw new ApiError('invalid', `Only a failed job can be retried; this one is ${job.status}`);
  Object.assign(job, { status: 'queued', attempts: 0, notBefore: null, error: null });
  saveJob_(job);
  return { job: presentJob_(job) };
}

function cancel_(req) {
  const job = jobOrThrow_(req.id).job;
  if (job.status !== 'queued') throw new ApiError('invalid', `Only a queued job can be cancelled; this one is ${job.status}`);
  if (job.state && job.state.videoId) throw new ApiError('invalid', 'This job already uploaded its video; delete it on the platform instead');
  job.status = 'cancelled';
  saveJob_(job);
  return { job: presentJob_(job) };
}

// ---- src/setup.js ----
/**
 * One-time setup, run from the Apps Script editor (select setup, press Run). Safe to run again:
 * it reuses the spreadsheet, trigger and tokens that already exist.
 */

function setup() {
  const p = props_();
  let ss = null;
  const id = p.getProperty('SHEET_ID');
  if (id) {
    try { ss = SpreadsheetApp.openById(id); } catch (err) { ss = null; }
  }
  if (!ss) {
    ss = SpreadsheetApp.create('Social Manager');
    p.setProperty('SHEET_ID', ss.getId());
  }
  let sh = ss.getSheetByName('Jobs');
  if (!sh) {
    sh = ss.getSheets()[0];
    sh.setName('Jobs');
  }
  sh.getRange(1, 1, 1, JOB_COLS.length).setValues([JOB_COLS]).setFontWeight('bold');
  sh.setFrozenRows(1);

  if (!ScriptApp.getProjectTriggers().some((t) => t.getHandlerFunction() === 'runQueue')) {
    ScriptApp.newTrigger('runQueue').timeBased().everyMinutes(5).create();
  }

  const lines = [`Jobs sheet: ${ss.getUrl()}`];
  try {
    const c = YouTube.whoami();
    lines.push(`YouTube channel: ${c.title} (${c.url}). If this is not the channel you want, see the FAQ.`);
  } catch (err) {
    lines.push(`YouTube check failed: ${err.message}`);
  }
  if (!Object.values(tokens_()).some((t) => t.admin)) {
    lines.push(`Admin token (shown once, keep it in a password manager): ${issueToken_('admin', true)}`);
  } else {
    lines.push('Admin token already exists; run resetAdminToken() if you lost it.');
  }
  console.log(lines.join('\n'));
}

/** Replaces the admin token, e.g. if it leaked. Other tokens keep working. */
function resetAdminToken() {
  replaceToken_('admin', true);
}

/** Issues (or replaces) the token Claude's scheduled jobs use. */
function createTokenForClaude() {
  replaceToken_('claude', false);
}

function replaceToken_(name, admin) {
  const all = tokens_();
  Object.keys(all).forEach((h) => { if (all[h].name === name) delete all[h]; });
  props_().setProperty('TOKENS', JSON.stringify(all));
  console.log(`Token for "${name}" (shown once): ${issueToken_(name, admin)}`);
}
